-- INFILL END

local World = workspace:FindFirstChild("World")
local Map = World and World:FindFirstChild("Map")
assert(Map, "workspace.World.Map not found")

local function r1(v) return math.floor(v * 10 + 0.5) / 10 end
local function vec(v) return { r1(v.X), r1(v.Y), r1(v.Z) } end
local function path(inst) return inst:GetFullName() end
local function bare(inst) return (inst:GetFullName():gsub("^Workspace%.", "")) end

-- world AABB of an oriented box
local function aabb(cf, size)
	local function ext(a)
		return (math.abs(cf.RightVector[a]) * size.X + math.abs(cf.UpVector[a]) * size.Y
			+ math.abs(cf.LookVector[a]) * size.Z) / 2
	end
	local e = Vector3.new(ext("X"), ext("Y"), ext("Z"))
	return cf.Position - e, cf.Position + e
end
local function boxOf(lo, hi) return { vec(lo), vec(hi) } end

local function partsUnder(inst)
	local n, lo, hi = 0, nil, nil
	local function take(p)
		n += 1
		local a, b = aabb(p.CFrame, p.Size)
		lo = lo and lo:Min(a) or a
		hi = hi and hi:Max(b) or b
	end
	if inst:IsA("BasePart") then take(inst) end
	for _, d in ipairs(inst:GetDescendants()) do
		if d:IsA("BasePart") then take(d) end
	end
	return n, lo, hi
end

local function underWorkspace(inst) return inst:IsDescendantOf(workspace) end

-- the top-level World.Map child an instance sits under ("" if none)
local function topOf(inst)
	local p = inst
	while p and p.Parent ~= Map do p = p.Parent end
	return p and p.Name or ""
end

local result = {}

-- Parts (every BasePart in workspace; workspace.Terrain counted separately)
local total, terrain = 0, 0
for _, d in ipairs(workspace:GetDescendants()) do
	if d:IsA("BasePart") then
		total += 1
		if d:IsA("Terrain") then terrain += 1 end
	end
end
result.Parts = total
result.TerrainParts = terrain

-- Baseplate
local bp = Map:FindFirstChild("Baseplate")
result.Baseplate = bp and bp:IsA("BasePart") and { Pos = vec(bp.Position), Size = vec(bp.Size) } or nil

-- MapChildren
result.MapChildren = {}
for _, c in ipairs(Map:GetChildren()) do
	local n, ulo, uhi = partsUnder(c)
	local e = { Name = c.Name, Class = c.ClassName, Parts = n, PartBox = ulo and boxOf(ulo, uhi) or nil }
	if c:IsA("PVInstance") then e.Pivot = vec(c:GetPivot().Position) end
	if c:IsA("Model") then
		local ok, cf, size = pcall(function() return c:GetBoundingBox() end)
		if ok and n > 0 then e.Box = boxOf(aabb(cf, size)) end
	elseif c:IsA("BasePart") then
		e.Box = boxOf(aabb(c.CFrame, c.Size))
	elseif ulo then
		e.Box = boxOf(ulo, uhi)
	end
	table.insert(result.MapChildren, e)
end

-- Areas
result.Areas = {}
for _, a in ipairs(CS:GetTagged("RenseiArea")) do
	if underWorkspace(a) then
		local lo, hi
		if a:IsA("BasePart") then
			lo, hi = aabb(a.CFrame, a.Size)
		elseif a:IsA("Model") then
			local cf, size = a:GetBoundingBox()
			lo, hi = aabb(cf, size)
		end
		table.insert(result.Areas, {
			AreaName = a:GetAttribute("AreaName") or a.Name, Top = topOf(a), Path = path(a),
			Box = lo and boxOf(lo, hi) or nil,
		})
	end
end

-- Arrivals
result.Arrivals = {}
for _, a in ipairs(CS:GetTagged("RenseiArrival")) do
	if underWorkspace(a) then
		table.insert(result.Arrivals, { Point = a:GetAttribute("Point") or "", Path = bare(a) })
	end
end

-- Trainers
result.Trainers = {}
for _, d in ipairs(workspace:GetDescendants()) do
	local id = d:GetAttribute("DialogueId")
	if type(id) == "string" and string.sub(id, 1, 8) == "trainer_" then
		table.insert(result.Trainers, {
			DialogueId = id, Path = path(d), Class = d.ClassName,
			Pivot = d:IsA("PVInstance") and vec(d:GetPivot().Position) or nil,
		})
	end
end

-- Spawns
result.Spawns = {}
for _, s in ipairs(CS:GetTagged("RenseiEnemySpawn")) do
	if underWorkspace(s) then
		local pos = s:IsA("PVInstance") and s:GetPivot().Position or nil
		table.insert(result.Spawns, {
			Name = s.Name, Path = path(s), Top = topOf(s), Pos = pos and vec(pos) or nil,
			EnemyType = s:GetAttribute("EnemyType"),
		})
	end
end

-- AlchemistSpawns children (they follow their site's slot; Ruling 7)
result.AlchemistSpawns = {}
local AS = Map:FindFirstChild("AlchemistSpawns")
if AS then
	for _, c in ipairs(AS:GetChildren()) do
		local pos = c:IsA("PVInstance") and c:GetPivot().Position or nil
		table.insert(result.AlchemistSpawns, { Name = c.Name, Class = c.ClassName, Pos = pos and vec(pos) or nil,
			EnemyType = c:GetAttribute("EnemyType") })
	end
end

-- World.EnemySpawns children (old hub spawns; Ruling 8)
result.EnemySpawns = {}
local ES = World:FindFirstChild("EnemySpawns")
if ES then
	for _, c in ipairs(ES:GetChildren()) do
		local pos = c:IsA("PVInstance") and c:GetPivot().Position or nil
		table.insert(result.EnemySpawns, { Name = c.Name, Class = c.ClassName, Path = path(c),
			Pos = pos and vec(pos) or nil, EnemyType = c:GetAttribute("EnemyType") })
	end
end

-- Retire
result.Retire = {}
local LM = Map:FindFirstChild("Lindenmoor")
for _, name in ipairs({ "NorthRoad", "HubRoad" }) do
	local r = LM and LM:FindFirstChild(name)
	if r then
		local n = partsUnder(r)
		table.insert(result.Retire, { Path = bare(r), Class = r.ClassName, Parts = n })
	end
end
result.BufferStops = {}
local TARGET = Vector3.new(-270, 10, -369)
for _, d in ipairs(workspace:GetDescendants()) do
	if d.Name == "BufferStop" and d:IsA("PVInstance") then
		local p = d:GetPivot().Position
		table.insert(result.BufferStops, { Path = bare(d), Pivot = vec(p) })
		if (p - TARGET).Magnitude <= 5 then
			table.insert(result.Retire, { Path = bare(d), Class = d.ClassName, Pivot = vec(p) })
		end
	end
end

-- GroundInInfill: World.Map.Ground BaseParts whose XZ centre lies in an Infill cell (half-open 4-stud cells)
local runs = HttpService:JSONDecode(INFILL) -- { {x0, z0, z1}, ... }: column x0..x0+4, rows z0..z1 (z1 exclusive)
local col = {}
local cells = 0
for _, r in ipairs(runs) do
	col[r[1]] = col[r[1]] or {}
	table.insert(col[r[1]], { r[2], r[3] })
	cells += (r[3] - r[2]) / 4
end
result.InfillCells = cells
result.GroundInInfill = 0
result.GroundInInfillSample = {}
local G = Map:FindFirstChild("Ground")
result.GroundParts = 0
if G then
	for _, d in ipairs(G:GetDescendants()) do
		if d:IsA("BasePart") then
			result.GroundParts += 1
			local p = d.Position
			local cx = math.floor(p.X / 4) * 4
			local list = col[cx]
			if list then
				for _, z in ipairs(list) do
					if p.Z >= z[1] and p.Z < z[2] then
						result.GroundInInfill += 1
						if #result.GroundInInfillSample < 25 then
							table.insert(result.GroundInInfillSample, { Path = path(d), Pos = vec(p), Size = vec(d.Size) })
						end
						break
					end
				end
			end
		end
	end
end

local json = HttpService:JSONEncode(result)
local sv = ServerStorage:FindFirstChild("LMSurvey") or Instance.new("StringValue")
sv.Name = "LMSurvey"
sv.Value = json
sv.Parent = ServerStorage
return "LMSurvey written: " .. #json .. " chars"
